CREATE TABLE failure_diagnoses (id UUID PRIMARY KEY,pipeline_run_id UUID NOT NULL REFERENCES pipeline_runs(id) ON DELETE CASCADE,failure_event_id UUID NOT NULL REFERENCES failure_events(id) ON DELETE CASCADE,fingerprint VARCHAR(64) NOT NULL,classification VARCHAR(64) NOT NULL,confidence NUMERIC(4,3) NOT NULL,confidence_level VARCHAR(16) NOT NULL,summary TEXT NOT NULL,probable_cause TEXT,recommended_action TEXT,classifier_version VARCHAR(64) NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT uq_diagnosis_event_version UNIQUE(failure_event_id,classifier_version));
CREATE TABLE diagnosis_evidence (id UUID PRIMARY KEY,diagnosis_id UUID NOT NULL REFERENCES failure_diagnoses(id) ON DELETE CASCADE,code VARCHAR(128) NOT NULL,category VARCHAR(64) NOT NULL,severity VARCHAR(32) NOT NULL,priority VARCHAR(32) NOT NULL,weight NUMERIC(4,3) NOT NULL,description TEXT NOT NULL,source VARCHAR(255),rule_id VARCHAR(128) NOT NULL,metadata JSONB);
CREATE INDEX idx_diagnoses_run ON failure_diagnoses(pipeline_run_id); CREATE INDEX idx_diagnoses_fingerprint ON failure_diagnoses(fingerprint);
